def dep_type(op):
    wide = {"reduceByKey", "groupByKey", "join", "distinct", "sortBy", "repartition"}
    return "宽依赖 需Shuffle" if op in wide else "窄依赖 无Shuffle"

ops = ["map", "filter", "mapValues", "union", "reduceByKey", "groupByKey", "join", "sample"]
for o in ops:
    print(f"{o:12s} -> {dep_type(o)}")
narrow = sum(1 for o in ops if "窄" in dep_type(o))
wide = len(ops) - narrow
print(f"结论: {len(ops)} 个算子中有 {narrow} 个窄依赖, {wide} 个宽依赖; 宽依赖是唯一触发 Shuffle 的来源")
